#include "../upstream/gframe/card_update.h"
#include <iostream>
#include <fstream>
#include <stdexcept>
#include <windows.h>
using namespace ygo;
int main(int argc,char** argv){try{CardUpdatePlan plan(argc>1?argv[1]:"../../work/update-sandbox");if(argc>3 && std::string(argv[3])=="network"){std::atomic<bool> cancel{false};unsigned callbacks=0;plan.Check(true,true,[](const std::string&){},cancel,[&](const CardDownloadProgress& p){++callbacks;});std::cout<<"PASS all selected sources download with live progress callbacks="<<callbacks<<std::endl;CardUpdatePlan cached(argv[1]);cached.Check(true,true,[](const std::string&){},cancel);std::cout<<"PASS repeated source check reuses checked cache; missing="<<cached.report.missing<<std::endl;return 0;}else plan.Prepare(argc>2?argv[2]:"../../work/update-research",true,true);auto r=plan.report;if(r.regular<15000 || r.pre<100 || r.cards.size()!=r.missing+r.changed)throw std::runtime_error("Real source counts or deduplicated differences are wrong");std::cout<<"CHECK local="<<r.local<<" regular="<<r.regular<<" pre="<<r.pre<<" missing="<<r.missing<<" changed="<<r.changed<<" script_changes="<<r.scriptChanges<<std::endl;if(argc>3){auto backup=plan.Install();std::cout<<"PASS installed and backed up "<<backup<<std::endl;CardUpdatePlan current(argv[1]);current.Prepare(argv[2],true,true);if(current.report.missing || current.report.changed || current.report.scriptChanges)throw std::runtime_error("Update did not eliminate differences");std::cout<<"RECHECK missing="<<current.report.missing<<" changed="<<current.report.changed<<" script_changes="<<current.report.scriptChanges<<std::endl;if(std::string(argv[3])!="installonly"){CardUpdatePlan::Restore(argv[1]);CardUpdatePlan prior(argv[1]);prior.Prepare(argv[2],true,true);if(prior.report.missing!=r.missing || prior.report.changed!=r.changed)throw std::runtime_error("Rollback did not restore exact prior card differences");std::cout<<"PASS rollback restores prior managed version"<<std::endl;}}return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}}
